import { amount } from "./index.mjs";
export const PUMP_ECONOMICS=Object.freeze({version:"pump-policy-v1-segment0",graduationMarketCapLeri:"65000000000",seedValueLeri:"15000000000",creatorReserveBps:1000,stages:[{id:"stage_one",bps:500,buyersMin:200,buyersTarget:250,marketCapLeri:"250000000000",sustainSeconds:259200},{id:"stage_two",bps:250,buyersMin:250,buyersTarget:400,marketCapLeri:"500000000000",sustainSeconds:345600},{id:"stage_three",bps:250,buyersMin:600,buyersTarget:1000,marketCapLeri:"1000000000000",sustainSeconds:345600,requiredSwaps:1000}]});
function requiredProof(proof,kind,token){if(!proof?.verified||proof.kind!==kind||proof.tokenId!==token.tokenId||proof.chainId!==token.chainId||!proof.reference||!/^([1-9][0-9]*)$/.test(proof.height||"")||!proof.blockHash)throw Error("CANONICAL_"+kind.toUpperCase()+"_PROOF_REQUIRED");}
export function graduationAccounting(input){
 const {token,price,proof}=input;if(!token?.verified||token.decimals!==6||!token.creator||!token.tokenId)throw Error("CANONICAL_SPO20_IDENTITY_REQUIRED");requiredProof(proof,"market_state",token);
 const now=input.now??Date.now(),priceTime=Date.parse(price?.windowEnd),maxAge=proof.priceMaxAgeSeconds;
 if(!Number.isSafeInteger(now)||!Number.isSafeInteger(maxAge)||maxAge<=0||!Number.isFinite(priceTime)||priceTime>now||now-priceTime>maxAge*1000)throw Error("CANONICAL_REFERENCE_PRICE_STALE_OR_POLICY_UNRESOLVED");
 if(!price?.available||!price.authoritative||!price.policyVersion||!price.provenance?.length||price.scale!=="1000000000000000000")throw Error("CANONICAL_REFERENCE_PRICE_REQUIRED");
 const p=amount(price.priceScaled),rioReserve=amount(input.realRioReserveUrio),circulating=amount(input.circulatingTokenBaseUnits),tokenPriceRio=amount(input.tokenSpotPriceRioScaled),scale=10n**18n;
 if(p===0n||circulating>amount(token.totalSupplyBaseUnits)||circulating===0n||tokenPriceRio===0n)throw Error("CANONICAL_MARKET_VALUE_UNAVAILABLE");
 // URI/leri both have six decimals. Market capitalization is not reserve cash.
 const marketCapLeri=circulating*tokenPriceRio*p/(scale*scale);
 if(marketCapLeri<amount(PUMP_ECONOMICS.graduationMarketCapLeri))throw Error("GENUINE_GRADUATION_THRESHOLD_NOT_REACHED");
 const seedLeri=amount(PUMP_ECONOMICS.seedValueLeri),requiredSeedUrio=(seedLeri*scale+p-1n)/p;
 if(requiredSeedUrio>rioReserve)throw Error("REQUIRED_LIQUIDITY_SEED_NOT_FUNDED");
 const surplusUrio=rioReserve-requiredSeedUrio,reserveUrio=surplusUrio*1000n/10000n;
 return {marketCapLeri:marketCapLeri.toString(),seedValueLeri:seedLeri.toString(),requiredSeedUrio:requiredSeedUrio.toString(),postSeedSurplusUrio:surplusUrio.toString(),creatorRewardReserveUrio:reserveUrio.toString(),ecosystemReserveUrio:(surplusUrio-reserveUrio).toString(),authority:"canonical_fixture_or_verified_adapter_only",policyVersion:PUMP_ECONOMICS.version};
}
export class MemoryPumpLifecycleStore {
 constructor(){this.tokens=new Map();this.tail=Promise.resolve();this.fixtureOnly=true;}
 async atomic(work){const prev=this.tail;let release;this.tail=new Promise(r=>release=r);await prev;try{return await work(this.tokens);}finally{release();}}
}
export async function recordTokenCreation(store,token,proof){return store.atomic(async tokens=>{requiredProof(proof,"creation",token);if(!token.verified||!token.creator||token.decimals!==6||!token.codeHash||!token.mintingLocked)throw Error("SPO20_CREATION_POLICY_NOT_PROVEN");const old=tokens.get(token.tokenId);if(old){if(old.creator!==token.creator||old.codeHash!==token.codeHash)throw Error("TOKEN_IDENTITY_CONFLICT");return structuredClone(old);}const row={...structuredClone(token),stage:"BONDING",claims:{},events:[structuredClone(proof)]};tokens.set(token.tokenId,row);return structuredClone(row);});}
export async function recordGraduation(store,tokenId,creator,input,proof){return store.atomic(async tokens=>{const token=tokens.get(tokenId);if(!token||token.creator!==creator)throw Error("CREATOR_TOKEN_AUTHORIZATION_MISMATCH");requiredProof(proof,"rio_liquidity_seed",token);if(token.stage!=="BONDING"){if(token.graduationProof?.reference===proof.reference)return structuredClone(token);throw Error("GRADUATION_REPLAY_OR_STATE_INVALID");}const accounting=graduationAccounting({...input,token});if(proof.nativeAmountUrio!==accounting.requiredSeedUrio||!proof.lpLocked||!proof.poolId)throw Error("CANONICAL_LP_SEED_PROOF_INSUFFICIENT");token.accounting=accounting;token.graduationProof=structuredClone(proof);token.stage="GRADUATED_RIO_POOL";token.events.push(structuredClone(proof));return structuredClone(token);});}
export async function reserveCreatorReward(store,tokenId,creator,stageId,evidence,idempotencyKey){return store.atomic(async tokens=>{const token=tokens.get(tokenId),stage=PUMP_ECONOMICS.stages.find(s=>s.id===stageId);if(!token||token.creator!==creator||!stage)throw Error("CREATOR_REWARD_AUTHORIZATION_MISMATCH");if(!["GRADUATED_RIO_POOL","RUSD_LIQUIDITY_VERIFIED","RIOEX_MARKET_VERIFIED"].includes(token.stage))throw Error("GRADUATION_NOT_VERIFIED");requiredProof(evidence,"reward_eligibility",token);if(!evidence.genuineBuyerAuthority||!Number.isSafeInteger(evidence.genuineBuyers)||evidence.genuineBuyers<stage.buyersMin||amount(evidence.marketCapLeri)<amount(stage.marketCapLeri)||evidence.sustainedSeconds<stage.sustainSeconds||!evidence.lpSeedVerified||!evidence.antiAbuseCleared||stage.requiredSwaps&&(evidence.verifiedSwaps<stage.requiredSwaps))throw Error("CREATOR_REWARD_ELIGIBILITY_UNPROVEN");if(!idempotencyKey)throw Error("IDEMPOTENCY_KEY_REQUIRED");if(token.claims[stageId]){if(token.claims[stageId].idempotencyKey!==idempotencyKey)throw Error("REWARD_STAGE_ALREADY_RESERVED");return structuredClone(token.claims[stageId]);}const quantity=amount(token.accounting.postSeedSurplusUrio)*BigInt(stage.bps)/10000n,used=Object.values(token.claims).reduce((n,c)=>n+amount(c.quantityUrio),0n);if(used+quantity>amount(token.accounting.creatorRewardReserveUrio))throw Error("CREATOR_REWARD_RESERVE_EXHAUSTED");const claim={stageId,idempotencyKey,creator,tokenId,quantityUrio:quantity.toString(),status:"RESERVED",evidenceReference:evidence.reference};token.claims[stageId]=claim;return structuredClone(claim);});}
export async function reconcileCreatorReward(store,tokenId,creator,stageId,proof){return store.atomic(async tokens=>{const token=tokens.get(tokenId),claim=token?.claims[stageId];if(!token||token.creator!==creator||!claim||claim.status!=="RESERVED")throw Error("REWARD_CLAIM_STATE_INVALID");requiredProof(proof,"reward_payment",token);if(proof.recipient!==creator||proof.quantityUrio!==claim.quantityUrio||!/^([A-Fa-f0-9]{64})$/.test(proof.txHash||"")||proof.code!==0)throw Error("CANONICAL_REWARD_PAYMENT_PROOF_REQUIRED");claim.status="CONFIRMED";claim.proof=structuredClone(proof);return structuredClone(claim);});}
export async function recordMarketTransition(store,tokenId,creator,kind,proof){return store.atomic(async tokens=>{const token=tokens.get(tokenId);if(!token||token.creator!==creator)throw Error("CREATOR_TOKEN_AUTHORIZATION_MISMATCH");if(kind==="RUSD_LIQUIDITY_VERIFIED"){if(token.stage!=="GRADUATED_RIO_POOL")throw Error("RUSD_TRANSITION_STATE_INVALID");requiredProof(proof,"rusd_liquidity",token);if(!proof.canonicalRusdIdentity||!proof.reserveAuthority||!proof.lpOwnerVerified||!proof.settlementVerified)throw Error("RUSD_LIQUIDITY_TRANSITION_UNPROVEN");}else if(kind==="RIOEX_MARKET_VERIFIED"){if(token.stage!=="RUSD_LIQUIDITY_VERIFIED")throw Error("RIOEX_MIGRATION_STATE_INVALID");requiredProof(proof,"rioex_migration",token);if(!proof.registryVerified||!proof.settlementVerified||!proof.supplyReconciled||!proof.poolOwnershipVerified)throw Error("RIOEX_MIGRATION_UNPROVEN");}else throw Error("UNSUPPORTED_LIFECYCLE_TRANSITION");token.stage=kind;token.events.push(structuredClone(proof));return structuredClone(token);});}
